alter table public.communication_templates add column if not exists event_key text;
alter table public.communication_templates add column if not exists requires_approval boolean not null default false;
create unique index if not exists uq_communication_templates_event_key on public.communication_templates(event_key) where event_key is not null;
create table if not exists public.communication_automation_rules (id uuid primary key default gen_random_uuid(),name text not null,event_key text not null,template_id uuid references public.communication_templates(id) on delete set null,audience text not null default 'parent',is_active boolean not null default true,created_at timestamptz not null default now());
create table if not exists public.communication_queue (id uuid primary key default gen_random_uuid(),event_key text not null,channel text not null default 'whatsapp',recipient_type text not null default 'parent',recipient_name text,recipient_phone text,parent_id uuid,student_id uuid,lead_id uuid,template_id uuid references public.communication_templates(id) on delete set null,message text,document_url text,status text not null default 'pending' check (status in ('pending','approved','sent','failed','cancelled')),requires_approval boolean not null default false,approved_by uuid,approved_at timestamptz,sent_at timestamptz,provider_message_id text,failure_reason text,created_at timestamptz not null default now());
create index if not exists idx_communication_queue_status on public.communication_queue(status,created_at desc);
create index if not exists idx_communication_queue_student on public.communication_queue(student_id,created_at desc);
alter table public.communication_automation_rules enable row level security;
alter table public.communication_queue enable row level security;
create policy "admins manage automation rules" on public.communication_automation_rules for all to authenticated using (public.is_admin_or_owner()) with check (public.is_admin_or_owner());
create policy "admins manage communication queue" on public.communication_queue for all to authenticated using (public.is_admin_or_owner()) with check (public.is_admin_or_owner());
insert into public.communication_templates(name,event_key,channel,category,body,active,requires_approval)
select * from (values
('New Enquiry','new_enquiry','whatsapp','utility','Dear Parent, thank you for your interest in Ramanujan Academy. Our counsellor will contact you shortly regarding your child’s admission enquiry.',true,false),
('Counselling Follow-up','counselling_followup','whatsapp','utility','Thank you for speaking with Ramanujan Academy. Please contact us if you need any further information about the course, batch or admission process.',true,false),
('Fee Payment Confirmation','fee_payment_received','whatsapp','utility','Dear Parent, we have received the fee payment for your child. Your receipt has been generated by Ramanujan Academy.',true,true),
('Fee Reminder','fee_reminder','whatsapp','utility','Dear Parent, this is a reminder regarding the pending fee installment for your child at Ramanujan Academy. Please contact our office for assistance.',true,false),
('Admission Confirmation','admission_confirmed','whatsapp','utility','Welcome to Ramanujan Academy. Your child’s admission has been confirmed.',true,false)
) v(name,event_key,channel,category,body,active,requires_approval)
where not exists (select 1 from public.communication_templates t where t.event_key=v.event_key);
alter table public.communication_queue add column if not exists recipient_type text not null default 'parent';
create or replace function public.queue_new_enquiry_whatsapp() returns trigger language plpgsql security definer set search_path=public as $$
declare t public.communication_templates%rowtype;
begin
 select * into t from public.communication_templates where event_key='new_enquiry' and active=true limit 1;
 if new.parent_phone is not null and t.id is not null then
  insert into public.communication_queue(event_key,channel,recipient_type,recipient_name,recipient_phone,template_id,message,status,requires_approval)
  values('new_enquiry','whatsapp','parent',coalesce(new.parent_name,new.name),new.parent_phone,t.id,t.body,'approved',false);
 end if;
 return new;
end $$;
drop trigger if exists trg_queue_new_enquiry_whatsapp on public.enquiries;
create trigger trg_queue_new_enquiry_whatsapp after insert on public.enquiries for each row execute function public.queue_new_enquiry_whatsapp();
create or replace function public.queue_fee_payment_whatsapp() returns trigger language plpgsql security definer set search_path=public as $$
declare t public.communication_templates%rowtype;
declare s public.students%rowtype;
declare p public.parents%rowtype;
begin
 select * into t from public.communication_templates where event_key='fee_payment_received' and active=true limit 1;
 select st.* into s from public.fee_accounts fa join public.students st on st.id=fa.student_id where fa.id=new.fee_account_id limit 1;
 if s.id is not null then select * into p from public.parents where id=s.parent_id limit 1; end if;
 if t.id is not null and coalesce(p.whatsapp_phone,p.phone) is not null then
  insert into public.communication_queue(event_key,channel,recipient_type,recipient_name,recipient_phone,student_id,parent_id,template_id,message,status,requires_approval)
  values('fee_payment_received','whatsapp','parent',coalesce(p.name,s.parent_name),coalesce(p.whatsapp_phone,p.phone),s.id,p.id,t.id,t.body,'pending',true);
 end if;
 return new;
end $$;
drop trigger if exists trg_queue_fee_payment_whatsapp on public.fee_payments;
create trigger trg_queue_fee_payment_whatsapp after insert on public.fee_payments for each row execute function public.queue_fee_payment_whatsapp();